e": "concept", "title": "transcendental philosophy"}, {"id": "dd03e075-d27d-439a-bb3a-a15f5e36d5ed", "type": "concept", "title": "Copernican turn"}], "description": "Students learn how Kant positions himself after Leibniz, Locke, Berkeley, Hume, and Newton."}, {"id": "c5a502e4-4414-4998-bf6a-10232d71d059", "type": "subtopic", "title": "Appearances and things in themselves", "children": [{"id": "6f96a731-e080-497b-9e4e-3d7a499a9e85", "type": "concept", "title": "appearance"}, {"id": "d7433e98-07b1-4c2e-bd63-e07796810de7", "type": "concept", "title": "thing in itself"}, {"id": "0c5c8647-bd57-47b2-8125-6a7600a90054", "type": "concept", "title": "phenomenon"}, {"id": "63bb33f2-8aef-4d40-bf8c-311d6b422dd1", "type": "concept", "title": "noumenon"}, {"id": "e167f5f7-eb2e-422b-84f0-3890b5bf6de4", "type": "concept", "title": "transcendental idealism"}, {"id": "67ee1121-15b3-4caf-be2a-3d29e62c0d44", "type": "concept", "title": "empirical realism"}, {"id": "6a7b1473-ce8a-4665-bc85-14481d4a6ca8", "type": "concept", "title": "intuition"}, {"id": "55230a57-d891-4f70-a079-bf48df8ff610", "type": "concept", "title": "concept"}, {"id": "72eb4570-4710-4a9a-8a1b-63476f5c2830", "type": "concept", "title": "faculty"}, {"id": "6e16127c-01fb-4923-8aa5-2d41cdd6fc94", "type": "concept", "title": "condition of possibility"}], "description": "This subtopic introduces Kant's framework for experience and its limits."}, {"id": "0a12f5d4-66ff-49a9-8be6-8c24c1c11bb4", "type": "subtopic", "title": "Synthetic a priori knowledge", "children": [{"id": "3dc01cc1-51ca-4e3d-95b3-d05f80e9fc18", "type": "concept", "title": "analytic judgment"}, {"id": "d080c324-1619-44c5-bc2d-f2825e530b4f", "type": "concept", "title": "synthetic judgment"}, {"id": "081a0acd-98db-4536-bf10-eda2fed8743c", "type": "concept", "title": "a priori"}, {"id": "d6787d79-05cf-4ccf-9f81-aa9ada3a4ea3", "type": "concept", "title": "a posteriori"}, {"id": "f8099455-772c-439a-9b23-e4a8e3d50af7", "type": "concept", "title": "synthetic a pri