, "title": "inequality"}, {"id": "f7546b22-60a1-4f47-ae71-3b7619b3e26c", "type": "concept", "title": "dependence"}, {"id": "cc75de57-3f81-4ff0-93aa-0aa37f6ad8c8", "type": "concept", "title": "civilization"}, {"id": "990cfa49-36c4-44eb-974e-21d255c49c3f", "type": "concept", "title": "Discourse on Inequality"}], "description": "Students learn Rousseau's genealogy of social dependence and inequality."}, {"id": "1d1c638d-6bc8-4296-89b2-88f02255d3b5", "type": "subtopic", "title": "Social contract and general will", "children": [{"id": "14dd9c5f-f905-455f-a646-d268e3b17fc9", "type": "concept", "title": "Social Contract"}, {"id": "724f003b-ff6f-4eb9-af19-8d2566aeee52", "type": "concept", "title": "general will"}, {"id": "ab48d702-cb92-4f50-bc49-30ac0e67a2f1", "type": "concept", "title": "sovereignty"}, {"id": "7ca81283-93b7-45aa-a970-cfaa9751d24f", "type": "concept", "title": "lawgiver"}, {"id": "a75d3418-b2cf-4e91-a514-e3ae304b5930", "type": "concept", "title": "civil freedom"}, {"id": "0f88a881-f00f-490f-beee-b265e1a55fd6", "type": "concept", "title": "moral freedom"}, {"id": "97245937-7cc7-40da-a91f-bc99cb8c4816", "type": "concept", "title": "popular sovereignty"}, {"id": "6ad383da-c21b-45ef-861a-65dae72f40a9", "type": "concept", "title": "association"}, {"id": "9c141b77-be1b-4a99-8b95-8d7d9890a298", "type": "concept", "title": "private will"}, {"id": "c50fbe84-e9b4-4832-a8aa-a6b198bb793b", "type": "concept", "title": "public will"}], "description": "This section examines Rousseau's attempt to reconcile authority and freedom."}, {"id": "062c3cbf-a93a-4313-a8ec-0fd68f8d1246", "type": "subtopic", "title": "Education, authenticity, and critique of progress", "children": [{"id": "0cb1ba9a-7d7d-470f-83ff-8373672e5083", "type": "concept", "title": "Emile"}, {"id": "9d5f21ba-4798-4aca-81ad-95c4b321532e", "type": "concept", "title": "natural education"}, {"id": "027ab586-a754-46ef-ba48-5a2f4d266671", "type": "concept", "title": "authenticity"}, {"id": "cc412301-568d-4cdb-8326-8